import { isComplexSchema } from "./isComplexSchema.js";

export const renderFileHeader = (kind: "query" | "mutation", method: string, path: string) => [
  "// ------------------------------",
  `// Auto-generated ${kind} file for ${method} ${path}`,
  "// This file is generated by Route Ink. Do not edit manually.",
  "// ------------------------------",
].join("\n");

/**
 * Renders a named import, or nothing when there is nothing to import. A
 * type-only import is emitted as `import type` so it is erased at runtime.
 */
export const renderImport = (from: string, values: string[], types: string[] = []): string | null => {
  if (values.length === 0 && types.length === 0) {
    return null;
  }

  if (values.length === 0) {
    return `import type { ${types.join(", ")} } from "${from}";`;
  }

  return `import { ${[...values, ...types.map((type) => `type ${type}`)].join(", ")} } from "${from}";`;
};

type SchemaReference = {
  declaration: string | null;
  ref: string;
};

/**
 * Complex schema expressions (e.g. `UserSchema.array()`) are hoisted into a
 * const so they can be used in `typeof` positions.
 */
export const getSchemaReference = (schema: string, constName: string): SchemaReference => isComplexSchema(schema)
  ? { declaration: `const ${constName} = ${schema};`, ref: constName }
  : { declaration: null, ref: schema };

export const joinLines = (lines: (string | null | false | undefined)[]) => lines
  .filter((line): line is string => typeof line === "string")
  .join("\n");

export const joinSections = (sections: (string | null | false | undefined)[]) => `${sections
  .filter((section): section is string => typeof section === "string" && section.length > 0)
  .join("\n\n")}\n`;
